package io.github.hoangtnedu.java.management;import io.github.hoangtnedu.java.orders.*;
@org.springframework.stereotype.Service public class ManagementService {private final OrderRepository repo;private final org.springframework.jdbc.core.JdbcTemplate jdbc;public ManagementService(OrderRepository r,org.springframework.jdbc.core.JdbcTemplate j){repo=r;jdbc=j;}
 @org.springframework.transaction.annotation.Transactional public void ship(long id,String username){try{Database.User user=Database.user(username);if(user==null||!java.util.List.of("MANAGER","ADMIN").contains(user.role()))throw new IllegalArgumentException("Manager required");Order o=repo.findById(id).orElseThrow();if(!"READY".equals(o.status))throw new IllegalArgumentException("Order not ready");o.status="SHIPPING";repo.saveAndFlush(o);jdbc.update("INSERT INTO order_status_history(order_id,old_status,new_status,changed_by,platform) VALUES(?,'READY','SHIPPING',?,'SPRING')",id,user.id());}catch(java.sql.SQLException e){throw new IllegalStateException(e);}}
}